// Real EC signatures and WebAuthn CBOR; no verifier stub or hardware attestation claim.
function rdCbor(mixed $value): string {
    $head=static fn(int $major,int $n)=>chr(($major<<5)|($n<24?$n:($n<256?24:25))).($n<24?'':($n<256?chr($n):pack('n',$n)));
    if(is_int($value))return $head($value<0?1:0,$value<0?-$value-1:$value);
    if(is_string($value))return $head(2,strlen($value)).$value;
    if(is_array($value)){$out=$head(5,count($value));foreach($value as$k=>$v){$out.=is_int($k)?rdCbor($k):$head(3,strlen($k)).$k;$out.=rdCbor($v);}return $out;}
    throw new RuntimeException('Unsupported fixture CBOR value');
}
